using System.Diagnostics;
using System.Text.Json.Nodes;

namespace SystemSift.Collectors;

public sealed class PowerShellCollector(string name, string script) : IDiagnosticCollector
{
    public string Name => name;
    public async Task<CollectorResult> CollectAsync(CollectionRequest request, IProgress<string>? progress, CancellationToken ct)
    {
        var sw = Stopwatch.StartNew(); progress?.Report($"Collecting {Name}");
        var wrapper = "$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);" +
            "Write-Output '__SYSTEMSIFT_JSON_BEGIN__';$result=@(& {" + script + "});$result | ConvertTo-Json -Depth 7 -Compress;Write-Output '__SYSTEMSIFT_JSON_END__'";
        try
        {
            var run = await CommandRunner.PowerShellAsync(wrapper, ct);
            var result = new CollectorResult { Name = Name, Elapsed = sw.Elapsed };
            if (run.TimedOut) { result.Status = CollectorStatus.Partial; result.Warnings.Add($"Command timed out after {Limits.CommandTimeout.TotalSeconds:N0} seconds."); return result; }
            if (run.ExitCode != 0) { result.Status = CollectorStatus.Unavailable; result.Errors.Add(DescribeFailure(run)); return result; }
            try { result.Data = JsonTools.ParsePowerShellJson(run.StdOut) ?? new JsonArray(); }
            catch (Exception ex) { result.Status = CollectorStatus.Failed; result.Errors.Add($"Structured PowerShell output could not be parsed: {ex.Message}"); if (!string.IsNullOrWhiteSpace(run.StdErr)) result.Errors.Add(run.StdErr.Trim()); return result; }
            result.RecordCount = result.Data is JsonArray array ? array.Count : result.Data is JsonObject packageObject && packageObject["packages"] is JsonArray packages ? packages.Count : result.Data is null ? 0 : 1;
            if (result.Data is JsonObject objectData && objectData["collectionPartial"] is JsonValue partial && partial.TryGetValue<bool>(out var isPartial) && isPartial)
            { result.Status = CollectorStatus.Partial; result.Warnings.Add("One or more meaningful subqueries were unavailable; available data was retained."); }
            return result;
        }
        catch (Exception ex) { return new CollectorResult { Name = Name, Status = CollectorStatus.Failed, Elapsed = sw.Elapsed, Errors = { ex.Message } }; }
    }
    private static string DescribeFailure((int ExitCode, string StdOut, string StdErr, bool TimedOut) run)
    {
        var details = !string.IsNullOrWhiteSpace(run.StdErr) ? run.StdErr.Trim() : run.StdOut.Trim();
        return $"Windows command exited with code {run.ExitCode}: {(string.IsNullOrWhiteSpace(details) ? "no diagnostic text was returned" : details[..Math.Min(details.Length, 1000)])}";
    }
}

public static class StandardCollectors
{
    public static IEnumerable<IDiagnosticCollector> Create() =>
    [
        new PowerShellCollector("Hardware", "[pscustomobject]@{machine=(Get-CimInstance Win32_ComputerSystem|Select-Object Manufacturer,Model,TotalPhysicalMemory);cpu=@(Get-CimInstance Win32_Processor|Select-Object Name,Manufacturer,NumberOfCores,NumberOfLogicalProcessors,MaxClockSpeed);baseboard=(Get-CimInstance Win32_BaseBoard|Select-Object Manufacturer,Product,Version,SerialNumber);bios=(Get-CimInstance Win32_BIOS|Select-Object Manufacturer,SMBIOSBIOSVersion,ReleaseDate,SerialNumber)}"),
        new PowerShellCollector("Storage", """$partial=$false;$items=@();try{$cim=@(Get-CimInstance Win32_DiskDrive);$disks=@(Get-Disk -ErrorAction Stop);$physical=@(Get-PhysicalDisk -ErrorAction Stop)}catch{$partial=$true;$cim=@();$disks=@();$physical=@()};foreach($d in $disks){try{$w=$cim|Where-Object {[int]$_.Index -eq [int]$d.Number}|Select-Object -First 1;$pd=$physical|Where-Object {$_.DeviceId -eq $d.Number -or ($_.SerialNumber -and $_.SerialNumber -eq $w.SerialNumber)}|Select-Object -First 1;$parts=@();foreach($p in @(Get-Partition -DiskNumber $d.Number -ErrorAction Stop)){$vol=$null;try{$vol=$p|Get-Volume -ErrorAction Stop}catch{};$parts+=[pscustomobject]@{partitionNumber=$p.PartitionNumber;offset=$p.Offset;size=$p.Size;type=$p.Type;gptType=$p.GptType;driveLetter=$p.DriveLetter;volume=if($vol){[pscustomobject]@{driveLetter=$vol.DriveLetter;fileSystem=$vol.FileSystem;fileSystemLabel=$vol.FileSystemLabel;size=$vol.Size;sizeRemaining=$vol.SizeRemaining;healthStatus=$vol.HealthStatus}}else{$null}}};$reliability=$null;try{if($pd){$reliability=$pd|Get-StorageReliabilityCounter -ErrorAction Stop|Select-Object Temperature,Wear,PowerOnHours,ReadErrorsTotal,WriteErrorsTotal,ReadErrorsUncorrected,WriteErrorsUncorrected,ReadLatencyMax,WriteLatencyMax,FlushLatencyMax,StartStopCycleCount,PowerCycleCount}}catch{$partial=$true};$items+=[pscustomobject]@{diskNumber=$d.Number;physicalDrive=('\\.\PHYSICALDRIVE'+$d.Number);model=if($w){$w.Model}else{$d.FriendlyName};manufacturer=if($w){$w.Manufacturer}else{$null};firmware=if($d.FirmwareVersion){$d.FirmwareVersion}elseif($w){$w.FirmwareRevision};busType=$d.BusType;interfaceType=if($w){$w.InterfaceType}else{$null};size=$d.Size;serialNumber=if($pd){$pd.SerialNumber}elseif($w){$w.SerialNumber};pnpDeviceId=if($w){$w.PNPDeviceID}else{$null};uniqueId=$d.UniqueId;objectId=$d.ObjectId;healthStatus=$d.HealthStatus;operationalStatus=($d.OperationalStatus -join ', ');partitions=$parts;reliability=$reliability}}catch{$partial=$true}};[pscustomobject]@{physicalDisks=$items;collectionPartial=$partial}"""),
        new PowerShellCollector("Graphics", "$gpus=@(Get-CimInstance Win32_VideoController|Select-Object Name,DriverVersion,DriverDate,VideoProcessor,CurrentHorizontalResolution,CurrentVerticalResolution);$nvidia=@();if($gpus.Name -match 'NVIDIA' -and (Get-Command nvidia-smi -ErrorAction SilentlyContinue)){ $nvidia=@(& nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits | ForEach-Object { $p=$_.Split(',');[pscustomobject]@{name=$p[0].Trim();driverVersion=$p[1].Trim();vramMiB=[int]$p[2].Trim();vramSource='nvidia-smi'} })};[pscustomobject]@{gpus=$gpus;nvidiaSmi=$nvidia;adapterRamNote='Win32_VideoController.AdapterRAM is intentionally omitted because it may be capped on modern GPUs.'}"),
        new PowerShellCollector("Drivers", """$services=@(Get-CimInstance Win32_SystemDriver -ErrorAction Stop);Get-CimInstance Win32_PnPSignedDriver|ForEach-Object {$d=$_;$service=$services|Where-Object {$_.Name -eq $d.DriverName -or ($d.DriverName -and $_.PathName -match [regex]::Escape($d.DriverName))}|Select-Object -First 1;[pscustomobject]@{deviceName=$d.DeviceName;deviceId=$d.DeviceID;pnpDeviceId=$d.DeviceID;driverProviderName=$d.DriverProviderName;driverVersion=$d.DriverVersion;driverDate=$d.DriverDate;infName=$d.InfName;driverName=$d.DriverName;deviceClass=$d.DeviceClass;manufacturer=$d.Manufacturer;isSigned=$d.IsSigned;associatedService=if($service){$service.Name}else{$null};serviceBinaryPath=if($service){$service.PathName}else{$null};serviceState=if($service){$service.State}else{$null}}}|Select-Object -First 2000"""),
        new PowerShellCollector("Problem devices", "$all=@(Get-PnpDevice);$present=@((Get-PnpDevice -PresentOnly).InstanceId);$non=@($all|Where-Object {$_.Problem -eq 45}|Select-Object FriendlyName,Class,InstanceId,Status,Problem);$active=@($all|Where-Object {$_.InstanceId -in $present -and $_.Problem -and $_.Problem -ne 45}|Select-Object FriendlyName,Class,InstanceId,Status,Problem);[pscustomobject]@{activeProblemDevices=$active;nonPresentDevices=$non;nonPresentCount=$non.Count}"),
        new PowerShellCollector("USB devices", "Get-PnpDevice -PresentOnly|Where-Object {$_.Class -eq 'USB' -or $_.InstanceId -match '^USB'}|Select-Object FriendlyName,Class,InstanceId,Status,Problem"),
        new PowerShellCollector("Audio devices", "Get-PnpDevice|Where-Object {$_.Class -in 'AudioEndpoint','MEDIA'}|Select-Object FriendlyName,Class,InstanceId,Status,Problem"),
        new PowerShellCollector("Services", "Get-CimInstance Win32_Service|Select-Object Name,DisplayName,State,StartMode,PathName,StartName|Select-Object -First 2000"),
        new PowerShellCollector("Scheduled tasks", """$tasks=@(Get-ScheduledTask|Where-Object {$_.TaskPath -notlike '\Microsoft*' -or $_.State -eq 'Disabled'}|ForEach-Object {$t=$_;try{$i=$null;try{$i=Get-ScheduledTaskInfo -TaskName $t.TaskName -TaskPath $t.TaskPath -ErrorAction Stop}catch{};$actions=@($t.Actions|Select-Object -First 8|ForEach-Object {[pscustomobject]@{actionType=$_.CimClass.CimClassName;execute=$_.Execute;arguments=$_.Arguments;workingDirectory=$_.WorkingDirectory}});$triggers=@($t.Triggers|Select-Object -First 12|ForEach-Object {[pscustomobject]@{triggerType=$_.CimClass.CimClassName;enabled=$_.Enabled;startBoundary=$_.StartBoundary;endBoundary=$_.EndBoundary;repetitionInterval=$_.Repetition.Interval;repetitionDuration=$_.Repetition.Duration;userId=$_.UserId}});[pscustomobject]@{taskName=$t.TaskName;taskPath=$t.TaskPath;state=if($null -ne $t.State){$t.State.ToString()}else{$null};enabled=if($null -ne $t.Settings){$t.Settings.Enabled}else{$null};author=$t.Author;isMicrosoft=($t.TaskPath -like '\Microsoft*');lastRunTime=if($null -ne $i -and $null -ne $i.LastRunTime){$i.LastRunTime.ToString('O')}else{$null};nextRunTime=if($null -ne $i -and $null -ne $i.NextRunTime){$i.NextRunTime.ToString('O')}else{$null};lastTaskResult=if($null -ne $i){$i.LastTaskResult}else{$null};actions=$actions;triggers=$triggers}}catch{[pscustomobject]@{taskName=$t.TaskName;taskPath=$t.TaskPath;collectionError=$_.Exception.Message}}});$tasks"""),
        new PowerShellCollector("Reliability History", "Get-CimInstance Win32_ReliabilityRecords -ErrorAction Stop|Select-Object @{n='timestamp';e={$_.TimeGenerated.ToString('O')}},SourceName,ProductName,EventIdentifier,Message,User"),
        new PowerShellCollector("Windows Update history", "$s=New-Object -ComObject Microsoft.Update.Session;$s.CreateUpdateSearcher().QueryHistory(0,200)|ForEach-Object {[pscustomobject]@{date=$_.Date.ToString('O');title=$_.Title;description=$_.Description;operation=$_.Operation.ToString();resultCode=$_.ResultCode.ToString()}}"),
        new PowerShellCollector("Network adapters", "$adapters=@(Get-NetAdapter|Select-Object Name,InterfaceDescription,Status,LinkSpeed,MacAddress,DriverInformation,Virtual);$ip=@(Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=True'|Select-Object Description,MACAddress,IPAddress,DefaultIPGateway,DNSServerSearchOrder,DHCPEnabled);$ssid=$null;try{$line=(& netsh wlan show interfaces|Select-String '^\\s*SSID\\s*:'|Select-Object -First 1).ToString();if($line){$ssid=($line -split ':',2)[1].Trim()}}catch{};[pscustomobject]@{adapters=$adapters;ipConfiguration=$ip;wifiSsid=$ssid}"),
        new PowerShellCollector("Power configuration", "[pscustomobject]@{activePlan=((& powercfg /getactivescheme|Out-String).Trim());supportedSleepStates=((& powercfg /a|Out-String).Trim());lastWakeSource=((& powercfg /lastwake|Out-String).Trim())}"),
        new PowerShellCollector("Security and virtualization", "$partial=$false;try{$dg=Get-CimInstance Win32_DeviceGuard -ErrorAction Stop|Select-Object VirtualizationBasedSecurityStatus,SecurityServicesConfigured,SecurityServicesRunning,AvailableSecurityProperties}catch{$dg=$null;$partial=$true};try{$def=Get-MpComputerStatus -ErrorAction Stop|Select-Object AMRunningMode,AntivirusEnabled,RealTimeProtectionEnabled}catch{$def=$null;$partial=$true};try{$secure=Confirm-SecureBootUEFI -ErrorAction Stop}catch{$secure=$null;$partial=$true};try{$hvci=(Get-ItemProperty 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\DeviceGuard\\Scenarios\\HypervisorEnforcedCodeIntegrity' -ErrorAction Stop).Enabled}catch{$hvci=$null;$partial=$true};try{$hypervisor=[bool]((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).HypervisorPresent)}catch{$hypervisor=$null;$partial=$true};[pscustomobject]@{deviceGuard=$dg;defender=$def;secureBoot=$secure;memoryIntegrityConfigured=$hvci;hypervisorPresent=$hypervisor;collectionPartial=$partial}"),
        new PowerShellCollector("Windows features", "Get-WindowsOptionalFeature -Online|Where-Object {$_.FeatureName -match 'Hyper-V|VirtualMachinePlatform|HypervisorPlatform|Microsoft-Windows-Subsystem-Linux|Containers-DisposableClientVM'}|Select-Object FeatureName,State"),
        new PowerShellCollector("AppX packages", """Get-AppxPackage|Select-Object Name,PackageFamilyName,Publisher,Version,Architecture,InstallLocation,IsFramework,IsResourcePackage,NonRemovable|Select-Object -First 2000"""),
        new WinGetCollector()
    ];
}
